// Independent auditor D13 service probe: actual PostgreSQL test database, actual engine workers,
// injected simulated UTC (DB sampler) with matching monotonic health time; qualification policy2 limit3.
// Removes only its own matches and its own release row.
import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import * as database from './packages/db/dist/index.js';
import { createMatchService } from './apps/match-service/dist/service.js';
import { createClockHealth } from './apps/match-service/dist/clock-health.js';
import { createEngineExecutor } from './apps/match-service/dist/engine-executor.js';
import { releases, using, cleanup } from './apps/match-service/tests/fixtures.mjs';

const POLICY = { schemaVersion: 2, id: 'qualification-dynamic-v1', profile: 'qualification', mode: 'dynamic', initialReserveMs: 150000, reserveCapMs: 150000, perActionBonusMs: 5000, perTurnPassBonusMs: 60000, resetTimeOnSkipMs: 60000, graceMs: 0, timeoutLimit: 3 };
const registry = releases(), releaseId = registry.active.releaseId;
const releaseExisted = await using('match', async c => (await c.query('SELECT 1 FROM match.releases WHERE release_id=$1', [releaseId])).rowCount === 1);
const out = {}, owned = [];
let utc = 1_900_000_000_000;
const T0 = utc;
const delay = { actor: null, ms: 0 };
const repository = database.createClockRepository('test', undefined, { sampleForTest: async () => utc });
function makeService(tag) {
  const base = createEngineExecutor();
  const executor = {
    execute: async job => { if (job.kind === 'transition' && delay.ms && job.command.actor === delay.actor) await new Promise(r => setTimeout(r, delay.ms)); return base.execute(job); },
    project: job => base.project(job), close: () => base.close(),
  };
  const health = createClockHealth({ monotonicNow: () => utc - T0 });
  return createMatchService({ repository, releases: registry, executor, clocks: { repository, health, runner: { enabled: false }, recoveryAuthority: async request => request.auditId === 'auditor-' + tag || request.auditId === 'auditor-any' ? request.auditId : null } });
}
let s = makeService('a');
const other = p => (p === 'p1' ? 'p2' : 'p1');
const clockOf = (id, p = 'p1') => s.readClock(p, { matchId: id });
const viewOf = (id, p = 'p1') => s.view(p, { matchId: id });
const cnt = (c, p) => c.players.find(x => x.playerId === p).timeoutCount;
async function tick(svc = s) { await svc.tickClocks(); }
let extra = null; // a second process that heartbeats alongside the first
async function advance(ms, svc = s) { while (ms > 0) { const step = Math.min(ms, 10000); utc += step; ms -= step; await tick(svc); if (extra) await extra.tickClocks().catch(() => {}); } }
async function runOut(id) { const c = await clockOf(id); assert.equal(c.status, 'running'); await advance(c.deadlineMs - utc); if (utc < c.deadlineMs) { utc = c.deadlineMs; await tick(); } }
const submit = (actor, id, v, move, input = {}, commandId = randomUUID(), svc = s) => svc.submit(actor, { matchId: id, commandId, expectedVersion: v, move, input });
const label = r => r.receipt ? r.receipt.outcome + '/' + (r.receipt.reason ?? '') : String(r);
async function db(id) {
  return using('match', async c => {
    const m = (await c.query('SELECT state_version,ended,winner FROM match.matches WHERE match_id=$1', [id])).rows[0];
    const receipts = (await c.query('SELECT actor_id,command_id,outcome,reason,state_version FROM match.command_receipts WHERE match_id=$1 ORDER BY state_version,actor_id', [id])).rows;
    const journal = (await c.query('SELECT count(*)::int n FROM match.journal WHERE match_id=$1', [id])).rows[0].n;
    const outbox = (await c.query('SELECT count(*)::int n FROM match.outbox WHERE match_id=$1', [id])).rows[0].n;
    const events = (await c.query('SELECT kind,operation_id FROM match.clock_events WHERE match_id=$1 ORDER BY clock_revision', [id])).rows;
    const clock = (await c.query('SELECT state FROM match.clocks WHERE match_id=$1', [id])).rows[0].state;
    return { stateVersion: Number(m.state_version), ended: m.ended, winner: m.winner, receipts, journal, outbox, events, clock };
  });
}
async function create(id) { owned.push(id); await s.create({ matchId: id, players: ['p1', 'p2'], clock: POLICY }); return (await viewOf(id)).priorityId; }
// Opening up to step n (0 = first-player choice pending, 3 = main game), all decisions instant; p1 goes first.
async function openTo(id, n) {
  const chooser = await create(id);
  let v = 0;
  for (let i = 0; i < n; i++) {
    const a = i === 0 ? chooser : (await clockOf(id)).activePlayerId;
    const r = i === 0 ? await submit(a, id, v, 'chooseWhoGoesFirst', { playerId: 'p1' }) : await submit(a, id, v, 'alterHand', { cardsToMulligan: [] });
    assert.equal(r.receipt.outcome, 'accepted'); v = r.receipt.stateVersion;
  }
  return v;
}
function terminalCheck(d, winner) {
  assert.equal(d.ended, true); assert.equal(d.winner, winner);
  const accepted = d.receipts.filter(r => r.outcome === 'accepted');
  assert.equal(Math.max(...accepted.map(r => Number(r.state_version))), d.stateVersion);
  assert.equal(new Set(accepted.map(r => Number(r.state_version))).size, accepted.length, 'two accepted receipts share a state version');
  assert.equal(d.journal, accepted.length, 'journal rows equal accepted receipts'); assert.equal(d.outbox, accepted.length, 'outbox rows equal accepted receipts');
  assert.equal(d.clock.status, 'ended');
}

try {
  // ---------- S1: opening timeouts end the game at once ----------
  out.S1 = [];
  for (let step = 0; step < 3; step++) {
    const id = 'audit-d13-s1-' + step + '-' + randomUUID();
    await openTo(id, step);
    const decider = (await clockOf(id)).activePlayerId;
    await runOut(id);
    const d = await db(id), view = await viewOf(id, other(decider)), clock = await clockOf(id, decider);
    terminalCheck(d, other(decider));
    assert.equal(view.endReason, 'timeout'); assert.equal(clock.status, 'ended'); assert.equal(cnt(clock, decider), 1); assert.equal(cnt(clock, other(decider)), 0); assert.equal(clock.timeoutLimit, 3);
    assert.ok(!d.events.some(e => e.kind === 'paused'), 'opening timeout must not pause');
    const sys = d.receipts.filter(r => r.actor_id.startsWith('system-clock'));
    assert.equal(sys.length, 1); assert.equal(sys[0].outcome, 'accepted');
    out.S1.push({ step, decider, endReason: view.endReason, stateVersion: d.stateVersion, systemReceipts: sys.length });
  }

  // ---------- S2: whole-game limit in the main game, with ordinary passes between timeouts ----------
  {
    const id = 'audit-d13-s2-' + randomUUID();
    let v = await openTo(id, 3);
    const seen = [];
    for (let k = 1; k <= 3; k++) {
      assert.equal((await clockOf(id)).activePlayerId, 'p1');
      await runOut(id);
      const c = await clockOf(id, 'p2'); seen.push({ timeout: k, p1Count: cnt(c, 'p1'), status: c.status });
      if (k < 3) {
        assert.equal(c.status, 'running'); assert.equal(cnt(c, 'p1'), k);
        v = (await viewOf(id)).stateVersion;
        for (const p of ['p2', 'p1', 'p2']) { utc += 1000; const r = await submit(p, id, v, 'passTurn'); assert.equal(r.receipt.outcome, 'accepted', 'pass ' + p); v = r.receipt.stateVersion; }
        assert.equal(cnt(await clockOf(id), 'p1'), k, 'ordinary passes do not change the count');
      }
    }
    const d = await db(id), view = await viewOf(id, 'p2'), c = await clockOf(id, 'p2');
    terminalCheck(d, 'p2'); assert.equal(view.endReason, 'timeout'); assert.equal(cnt(c, 'p1'), 3); assert.equal(c.status, 'ended');
    const late = await submit('p2', id, d.stateVersion, 'passTurn').then(label, e => 'error:' + e.code); assert.ok(!late.startsWith('accepted'));
    assert.equal((await db(id)).stateVersion, d.stateVersion);
    out.S2 = { seen, stateVersion: d.stateVersion, systemReceipts: d.receipts.filter(r => r.actor_id.startsWith('system-clock')).length, lateMove: late };
  }

  // ---------- S3: outage, recovery pause and audited resume never count; one real timeout counts once ----------
  {
    const id = 'audit-d13-s3-' + randomUUID();
    await openTo(id, 3);
    await advance(100000);
    const before = await clockOf(id);
    utc += 600000; // the whole process is gone for ten minutes, past p1's deadline
    s = makeService('b'); // a fresh process after the outage
    for (let i = 0; i < 4; i++) { utc += 1000; await tick(); }
    const d1 = await db(id);
    const pausedClock = await clockOf(id);
    out.S3 = { afterOutage: { status: pausedClock.status, pauseReason: pausedClock.pauseReason, p1Count: cnt(pausedClock, 'p1'), p1Remaining: pausedClock.players.find(p => p.playerId === 'p1').remainingMs, before: before.players.find(p => p.playerId === 'p1').remainingMs } };
    assert.equal(pausedClock.status, 'paused'); assert.equal(cnt(pausedClock, 'p1'), 0); assert.equal(d1.ended, false);
    // concession while paused (D13 says "at any point")
    const pc = await submit('p2', id, d1.stateVersion, 'concede').then(label, e => 'error:' + (e.code ?? e.message));
    const ac = await submit('p1', id, d1.stateVersion, 'concede').then(label, e => 'error:' + (e.code ?? e.message));
    out.S3.concedeWhilePaused = { waiting: pc, active: ac };
    // audits cannot choose a winner or forfeit
    const forged = [];
    for (const extra of [{ winner: 'p2' }, { reason: 'timeout' }, { forfeit: true }]) forged.push(await s.resumeClock({ matchId: id, expectedStateVersion: d1.stateVersion, expectedClockRevision: pausedClock.clockRevision, operationId: randomUUID(), auditId: 'auditor-b', ...extra }).then(() => 'accepted', e => e.code));
    forged.push(await s.pauseClock({ matchId: id, expectedStateVersion: d1.stateVersion, expectedClockRevision: pausedClock.clockRevision, operationId: randomUUID(), auditId: 'auditor-b', reason: 'timeout' }).then(() => 'accepted', e => e.code));
    out.S3.forgedAudits = forged; assert.ok(forged.every(x => x === 'INVALID_REQUEST'));
    await s.resumeClock({ matchId: id, expectedStateVersion: d1.stateVersion, expectedClockRevision: pausedClock.clockRevision, operationId: randomUUID(), auditId: 'auditor-b' });
    const resumed = await clockOf(id);
    out.S3.afterResume = { status: resumed.status, p1Count: cnt(resumed, 'p1'), p1Remaining: resumed.players.find(p => p.playerId === 'p1').remainingMs };
    assert.equal(resumed.status, 'running'); assert.equal(cnt(resumed, 'p1'), 0);
    await runOut(id);
    const after = await clockOf(id, 'p2'); out.S3.afterRealTimeout = { status: after.status, p1Count: cnt(after, 'p1') };
    assert.equal(cnt(after, 'p1'), 1); assert.equal(after.status, 'running');
  }

  // ---------- S4: players cannot send forfeitGame ----------
  {
    const id = 'audit-d13-s4-' + randomUUID();
    const v = await openTo(id, 3);
    out.S4 = [];
    for (const [actor, input] of [['p1', { winnerId: 'p1', reason: 'timeout' }], ['p2', { winnerId: 'p2', reason: 'timeout' }], ['p2', {}]]) out.S4.push(await submit(actor, id, v, 'forfeitGame', input).then(label, e => 'error:' + e.code));
    const d = await db(id); assert.equal(d.ended, false); assert.equal(d.stateVersion, v);
    assert.ok(out.S4.every(x => !x.startsWith('accepted')));
  }

  // ---------- S5: waiting opening concession stays unreserved and ends the game ----------
  out.S5 = [];
  for (let step = 0; step < 3; step++) {
    const id = 'audit-d13-s5-' + step + '-' + randomUUID();
    const v = await openTo(id, step);
    const decider = (await clockOf(id)).activePlayerId, waiting = other(decider);
    const eventsBefore = (await db(id)).events.length;
    // delayed waiting concession: the active decision is neither busy nor fenced, the concession then goes stale
    delay.actor = waiting; delay.ms = 400;
    const pending = submit(waiting, id, v, 'concede');
    await new Promise(r => setTimeout(r, 100));
    const move = step === 0 ? submit(decider, id, v, 'chooseWhoGoesFirst', { playerId: 'p1' }) : submit(decider, id, v, 'alterHand', { cardsToMulligan: [] });
    const [w, a] = await Promise.all([pending, move]); delay.ms = 0;
    assert.equal(a.receipt.outcome, 'accepted', 'active decision while waiting concession in flight');
    assert.equal(w.receipt.outcome, 'stale');
    // undelayed waiting concession now ends the game; no reservation event is written for it
    const v2 = a.receipt.stateVersion, nextDecider = (await clockOf(id)).activePlayerId, conceder = other(nextDecider);
    const eventsMid = (await db(id)).events.length;
    const c = await submit(conceder, id, v2, 'concede');
    const d = await db(id), view = await viewOf(id, nextDecider);
    assert.equal(c.receipt.outcome, 'accepted'); terminalCheck(d, nextDecider); assert.equal(view.endReason, 'concession');
    const newEvents = d.events.slice(eventsMid).map(e => e.kind);
    assert.deepEqual(newEvents, ['accepted'], 'waiting concession wrote only its final event');
    out.S5.push({ step, delayedWaiting: label(w), active: label(a), concession: label(c), eventsDuringDelayedPhase: eventsMid - eventsBefore, newEvents });
  }

  // ---------- S6: races at the deadline ----------
  const s2 = makeService('c'); extra = s2; // a second process
  const races = { opening: {}, main: {} };
  for (let trial = 0; trial < 24; trial++) {
    const main = trial % 2 === 1;
    const id = 'audit-d13-s6-' + trial + '-' + randomUUID();
    let v = await openTo(id, main ? 3 : trial % 3);
    if (main) { // p1 already has two timeouts
      for (let k = 0; k < 2; k++) { await runOut(id); v = (await viewOf(id)).stateVersion; utc += 500; const r = await submit('p2', id, v, 'passTurn'); assert.equal(r.receipt.outcome, 'accepted'); v = r.receipt.stateVersion; }
      assert.equal(cnt(await clockOf(id), 'p1'), 2);
    }
    const c = await clockOf(id), active = c.activePlayerId;
    await advance(Math.max(0, c.deadlineMs - utc - 10000));
    utc = c.deadlineMs + Math.floor(Math.random() * 40);
    await s2.tickClocks().catch(() => {}); // keep the second process's health continuous at the same time
    const jitter = () => new Promise(r => setTimeout(r, Math.floor(Math.random() * 12)));
    const ops = {
      sweepA: jitter().then(() => s.tickClocks()).then(() => 'done', e => 'error:' + e.code),
      sweepB: jitter().then(() => s2.tickClocks()).then(() => 'done', e => 'error:' + e.code),
      activeConcede: jitter().then(() => submit(active, id, v, 'concede')).then(label, e => 'error:' + e.code),
      waitingConcede: jitter().then(() => submit(other(active), id, v, 'concede')).then(label, e => 'error:' + e.code),
      activeMove: jitter().then(() => main ? submit(active, id, v, 'passTurn') : submit(active, id, v, 'alterHand', { cardsToMulligan: [] })).then(label, e => 'error:' + e.code),
    };
    const res = Object.fromEntries(await Promise.all(Object.entries(ops).map(async ([k, p]) => [k, await p])));
    await tick(); await s2.tickClocks().catch(() => {});
    const d = await db(id);
    const terminal = d.receipts.filter(r => r.outcome === 'accepted' && Number(r.state_version) === d.stateVersion);
    let outcome;
    if (d.ended) {
      terminalCheck(d, d.winner); assert.equal(terminal.length, 1);
      const t = terminal[0]; outcome = t.actor_id.startsWith('system-clock') ? 'timeout' : t.actor_id === active ? 'activeConcede' : 'waitingConcede';
      const view = await viewOf(id); assert.equal(view.endReason, outcome === 'timeout' ? 'timeout' : 'concession');
      if (outcome === 'timeout') assert.equal(d.winner, other(active)); else assert.equal(d.winner, outcome === 'activeConcede' ? other(active) : active);
    } else outcome = 'notEnded:' + d.clock.status;
    assert.equal(d.receipts.filter(r => r.actor_id.startsWith('system-clock')).length, (main ? 2 : 0) + (outcome === 'timeout' ? 1 : 0), 'exactly one timeout receipt per real timeout');
    const bucket = races[main ? 'main' : 'opening']; bucket[outcome] = (bucket[outcome] ?? 0) + 1;
    for (const [k, r] of Object.entries(res)) { const key = k + '=' + r; bucket[key] = (bucket[key] ?? 0) + 1; }
  }
  out.S6 = races;
  extra = null; await s2.close?.();
} catch (error) { out.error = String(error && error.stack || error); } finally {
  for (const id of owned) await cleanup(id).catch(() => {});
  const left = await using('match', async c => (await c.query("SELECT count(*)::int n FROM match.matches WHERE match_id LIKE 'audit-d13-%'")).rows[0].n);
  let releaseRemoved = false;
  if (!releaseExisted) releaseRemoved = await using('match', async c => (await c.query('DELETE FROM match.releases r WHERE release_id=$1 AND NOT EXISTS (SELECT 1 FROM match.matches m WHERE m.release_id=r.release_id)', [releaseId])).rowCount === 1).catch(e => 'error:' + e.message);
  out.cleanup = { ownedMatches: owned.length, remainingAuditMatches: left, releaseExisted, releaseRemoved };
  await s.close?.();
  console.log(JSON.stringify(out));
  if (out.error) process.exitCode = 1;
}
